const store=$getWorkflowStaticData('global');

if (!store.users) store.users={};
if (!store.jobs) store.jobs=[];

const m=$json.message ?? {};
const text=(m.text ?? '').trim();

const chatId=m.chat?.id;
const telegramId=String(m.from?.id ?? '');

if (!chatId || !telegramId) {
  return [];
}

if (!store.users[telegramId]) {
  store.users[telegramId]={
    telegram_id:telegramId,
    chat_id:chatId,
    username:m.from?.username ?? '',
    first_name:m.from?.first_name ?? '',
    language:'ar-SA',
    voice:'ar-SA-HamedNeural',
    video_aspect:'9:16',
    awaiting:null,
    pending_title:null,
    pending_topic:null,
    pending_style:null,
    created_at:new Date().toISOString()
  };
}

const user=store.users[telegramId];

user.chat_id=chatId;
user.username=m.from?.username ?? user.username ?? '';
user.first_name=m.from?.first_name ?? user.first_name ?? '';
user.last_seen_at=new Date().toISOString();

const STYLE_OPTIONS={
  '1':{key:'realistic',label:'واقعي'},
  '2':{key:'cartoon',label:'كرتوني'},
  '3':{key:'illustration',label:'رسومي / Motion Graphics'},
  '4':{key:'3d',label:'ثلاثي الأبعاد 3D'},
  '5':{key:'futuristic',label:'تقني / مستقبلي'},
  '6':{key:'auto',label:'تلقائي'}
};

function resolveStyle(value) {
  const raw=String(value || '').trim().toLowerCase();

  if (STYLE_OPTIONS[raw]) {
    return STYLE_OPTIONS[raw];
  }

  const aliases={
    'واقعي':'1',
    'realistic':'1',

    'كرتوني':'2',
    'كرتون':'2',
    'cartoon':'2',

    'رسومي':'3',
    'رسوم':'3',
    'illustration':'3',
    'motion graphics':'3',

    '3d':'4',
    'ثلاثي الأبعاد':'4',
    'ثلاثي الابعاد':'4',

    'تقني':'5',
    'مستقبلي':'5',
    'futuristic':'5',

    'تلقائي':'6',
    'auto':'6'
  };

  const id=aliases[raw];
  return id ? STYLE_OPTIONS[id] : null;
}

function styleMenu(prefix='') {
  return `${prefix}🎨 اختر نمط المشاهد:

1️⃣ واقعي
2️⃣ كرتوني
3️⃣ رسومي / Motion Graphics
4️⃣ ثلاثي الأبعاد 3D
5️⃣ تقني / مستقبلي
6️⃣ تلقائي

أرسل الرقم من 1 إلى 6.`;
}

let command='';

if (text.startsWith('/')) {
  command=text
    .split(/\s+/)[0]
    .split('@')[0]
    .toLowerCase();
}

let route='reply';
let reply='';

let videoTitle='';
let videoSubject='';
let videoScript='';
let scriptMode='';
let visualStyle='auto';
let visualStyleLabel='تلقائي';
let taskId='';

if (command === '/start') {

  user.awaiting=null;
  user.pending_title=null;
  user.pending_topic=null;
  user.pending_style=null;

  reply=
`🎬 Pingoo Video جاهز

/video إنشاء فيديو تلقائي
/script إدخال سكربت يدوي
/status حالة الطلب
/history السجل
/settings الإعدادات
/cancel إلغاء الطلب`;

} else if (command === '/video') {

  videoSubject=text
    .replace(/^\/video(?:@\w+)?/i,'')
    .trim();

  user.pending_title=null;
  user.pending_style=null;

  if (!videoSubject) {

    user.awaiting='video_topic';
    user.pending_topic=null;

    reply=
`🎬 أرسل الآن موضوع الفيديو.

مثال:
فوائد النوم الجيد وتأثيره على الدماغ`;

  } else {

    user.pending_topic=videoSubject;
    user.awaiting='video_style';

    reply=styleMenu(
`✅ تم حفظ الموضوع:
${videoSubject}

`
    );
  }

} else if (command === '/script') {

  user.pending_title=null;
  user.pending_topic=null;
  user.pending_style=null;
  user.awaiting='manual_title';

  reply=
`✍️ وضع السكربت اليدوي

1️⃣ أرسل الآن عنوان الفيديو.`;

} else if (
  !command &&
  user.awaiting === 'manual_title' &&
  text
) {

  user.pending_title=text;
  user.awaiting='manual_topic';

  reply=
`✅ تم حفظ العنوان:
${text}

2️⃣ أرسل الآن موضوع الفيديو.`;

} else if (
  !command &&
  user.awaiting === 'manual_topic' &&
  text
) {

  user.pending_topic=text;
  user.pending_style=null;
  user.awaiting='manual_style';

  reply=styleMenu(
`✅ تم حفظ الموضوع:
${text}

3️⃣ `
  );

} else if (
  !command &&
  user.awaiting === 'manual_style' &&
  text
) {

  const selected=resolveStyle(text);

  if (!selected) {

    reply=styleMenu(
`❌ الاختيار غير صحيح.

`
    );

  } else {

    user.pending_style=selected.key;
    user.awaiting='manual_script';

    reply=
`✅ نمط المشاهد:
${selected.label}

4️⃣ أرسل الآن السكربت كاملًا.`;
  }

} else if (
  !command &&
  user.awaiting === 'manual_script' &&
  text
) {

  videoTitle=String(user.pending_title || '').trim();
  videoSubject=String(user.pending_topic || '').trim();

  const selected=
    Object.values(STYLE_OPTIONS)
      .find(s => s.key === user.pending_style)
    || STYLE_OPTIONS['6'];

  visualStyle=selected.key;
  visualStyleLabel=selected.label;
  videoScript=text;

  user.awaiting=null;
  user.pending_title=null;
  user.pending_topic=null;
  user.pending_style=null;

  route='video';
  scriptMode='manual';

  reply=
`✅ تم استلام السكربت اليدوي.

🎬 العنوان:
${videoTitle}

📝 الموضوع:
${videoSubject}

🎨 نمط المشاهد:
${visualStyleLabel}

جاري إنشاء الفيديو...`;

} else if (
  !command &&
  user.awaiting === 'video_topic' &&
  text
) {

  user.pending_topic=text;
  user.pending_style=null;
  user.awaiting='video_style';

  reply=styleMenu(
`✅ تم حفظ الموضوع:
${text}

`
  );

} else if (
  !command &&
  user.awaiting === 'video_style' &&
  text
) {

  const selected=resolveStyle(text);

  if (!selected) {

    reply=styleMenu(
`❌ الاختيار غير صحيح.

`
    );

  } else {

    videoSubject=String(user.pending_topic || '').trim();

    visualStyle=selected.key;
    visualStyleLabel=selected.label;

    user.awaiting=null;
    user.pending_topic=null;
    user.pending_style=null;

    route='video';
    scriptMode='auto';

    reply=
`⏳ تم استلام الطلب.

🎬 الموضوع:
${videoSubject}

🎨 نمط المشاهد:
${visualStyleLabel}

جاري تجهيز السكربت وإنشاء المهمة...`;
  }

} else if (command === '/status') {

  const job=store.jobs.find(
    j => String(j.telegram_id) === telegramId
  );

  if (!job) {
    reply='📊 لا توجد لديك مهمة محفوظة حتى الآن.';
  } else {
    route='status';
    taskId=job.task_id;
  }

} else if (command === '/history') {

  const jobs=store.jobs
    .filter(j => String(j.telegram_id) === telegramId)
    .slice(0,5);

  if (!jobs.length) {
    reply='📚 السجل فارغ.';
  } else {
    reply=
      '📚 آخر المهام\n\n' +
      jobs.map(
        (j,i) =>
`${i+1}. ${j.title || j.topic}
${j.task_id}
${j.status}`
      ).join('\n\n');
  }

} else if (command === '/settings') {

  reply=
`⚙️ الإعدادات الحالية

اللغة: ${user.language}
الصوت: ${user.voice}
المقاس: ${user.video_aspect}

🎨 نمط المشاهد:
يتم اختياره لكل فيديو`;

} else if (command === '/cancel') {

  user.awaiting=null;
  user.pending_title=null;
  user.pending_topic=null;
  user.pending_style=null;

  reply='❌ تم إلغاء أي طلب إدخال غير مكتمل.';

} else {

  reply=
`الأمر غير معروف.

استخدم /start لعرض الأوامر.`;
}

return [{
  json:{
    chat_id:chatId,
    telegram_id:telegramId,
    username:user.username,

    command,
    route,
    task_id:taskId,

    video_title:videoTitle,
    video_subject:videoSubject,
    video_script:videoScript,

    script_mode:scriptMode,

    visual_style:visualStyle,
    visual_style_label:visualStyleLabel,

    video_language:user.language,
    voice_name:user.voice,
    video_aspect:user.video_aspect,

    reply
  }
}];

const ctxItems = $items('Video Gate');
const ctx = ctxItems.length ? ctxItems[0].json : {};

const taskId = $json?.data?.task_id;

if (!taskId) {
  return [{
    json: {
      chat_id: ctx.chat_id,
      task_reply:
`❌ لم يتم إنشاء المهمة في MoneyPrinterTurbo.

الاستجابة:
${JSON.stringify($json)}`
    }
  }];
}

const store = $getWorkflowStaticData('global');

if (!store.jobs) {
  store.jobs = [];
}

const job = {
  telegram_id: String(ctx.telegram_id),
  chat_id: ctx.chat_id,
  task_id: taskId,
  title: $json.video_title || $json.video_subject,
    topic: ctx.video_subject,
  status: 'submitted',
  progress: 0,
  created_at: new Date().toISOString()
};

store.jobs.unshift(job);

// نحتفظ بآخر 100 مهمة فقط
store.jobs = store.jobs.slice(0,100);

return [{
  json: {
    ...ctx,
    task_id: taskId,
    task_reply:
`✅ تم إنشاء مهمة الفيديو

🎬 الموضوع:
${ctx.video_subject}

🆔 Task ID:
${taskId}

يمكنك استخدام /status لمتابعة الحالة.`
  }
}];

const ctxItems = $items('Status Gate');

if (!ctxItems.length) {
  throw new Error('STATUS_CONTEXT_NOT_FOUND');
}

const ctx = ctxItems[0].json;

const payload = $json?.data;

if (!payload) {
  throw new Error(
    'INVALID_STATUS_RESPONSE: ' +
    JSON.stringify($json)
  );
}

const store = $getWorkflowStaticData('global');

if (!store.jobs) {
  store.jobs = [];
}

const index = store.jobs.findIndex(
  j =>
    String(j.telegram_id) === String(ctx.telegram_id) &&
    j.task_id === ctx.task_id
);

let status = 'processing';

if (
  payload.state === -1 ||
  payload.failed_stage ||
  payload.error
) {
  status = 'failed';
} else if (
  Number(payload.progress || 0) >= 100
) {
  status = 'completed';
}

if (index >= 0) {
  store.jobs[index] = {
    ...store.jobs[index],
    status,
    state: payload.state,
    progress: Number(payload.progress || 0),
    failed_stage: payload.failed_stage ?? null,
    error: payload.error ?? null,
    videos: payload.videos ?? null,
    combined_videos: payload.combined_videos ?? null,
    audio_file: payload.audio_file ?? null,
    updated_at: new Date().toISOString()
  };
}

let message =
`📊 حالة الفيديو

🎬 الموضوع:
${index >= 0 ? store.jobs[index].topic : ''}

🆔 Task ID:
${ctx.task_id}

📈 التقدم:
${payload.progress ?? 0}%

⚙️ الحالة:
${status}`;

if (payload.failed_stage) {
  message += `

❌ مرحلة الفشل:
${payload.failed_stage}`;
}

if (payload.error) {
  message += `

⚠️ الخطأ:
${payload.error}`;
}

if (status === 'completed') {
  message += `

✅ الفيديو مكتمل`;
}

return [{
  json:{
    chat_id:ctx.chat_id,
    telegram_id:ctx.telegram_id,
    task_id:ctx.task_id,
    real_status:status,
    progress:Number(payload.progress || 0),
    state:payload.state,
    status_reply:message
  }
}];

const topic=String(
  $json.video_subject || ''
).trim();

const title=String(
  $json.video_title || ''
).trim();

const providedScript=String(
  $json.video_script || ''
).trim();

const visualStyle=String(
  $json.visual_style || 'auto'
).trim().toLowerCase();

if (!topic) {
  throw new Error('VIDEO_TOPIC_EMPTY');
}

const STYLE_SEARCH={
  realistic:'cinematic realistic footage',
  cartoon:'cartoon animation',
  illustration:'motion graphics animated illustration',
  '3d':'3d animation render',
  futuristic:'futuristic technology cinematic',
  auto:''
};

const suffix=
  STYLE_SEARCH[visualStyle]
  ?? '';

const script=providedScript || (
`اليوم سنتحدث باختصار عن ${topic}.
سنشرح أهم عناصر الموضوع بطريقة واضحة ومباشرة.
سنشاهد أمثلة تساعد على فهم ${topic} بصورة أفضل.
وفي النهاية سنلخص أهم النقاط التي يجب تذكرها.`
);

const stopWords=new Set([
  'في','من','على','إلى','الى','عن','مع',
  'هذا','هذه','ذلك','تلك','هو','هي',
  'ثم','كما','قد','لقد','يمكن','يكون',
  'تكون','أن','إن','اذا','إذا','عندما',
  'بعد','قبل','كل','أو','او','و',
  'هل','ما','ماذا','لماذا','كيف'
]);

function normalizeWords(text) {
  return String(text || '')
    .replace(/[،,؛;:()"']/g,' ')
    .replace(/\s+/g,' ')
    .trim();
}

function compactScene(text) {

  const normalized=
    normalizeWords(text);

  if (!normalized) {
    return '';
  }

  const words=
    normalized.split(/\s+/);

  const meaningful=
    words.filter(
      word =>
        word.length > 1 &&
        !stopWords.has(word)
    );

  const chosen=
    meaningful.length >= 3
      ? meaningful
      : words;

  return chosen
    .slice(0,8)
    .join(' ');
}

function styledTerm(base) {

  const clean=
    compactScene(base);

  if (!clean) {
    return '';
  }

  return suffix
    ? `${clean} ${suffix}`
    : clean;
}

const sceneBases=[];

function addScene(value) {

  const clean=
    compactScene(value);

  if (
    clean.length >= 5 &&
    !sceneBases.includes(clean)
  ) {
    sceneBases.push(clean);
  }
}

/*
 * Build search terms in narration order.
 * Each sentence becomes a visual scene concept.
 */
const sentences=
  script
    .split(/[.!؟\n]+/u)
    .map(x => x.trim())
    .filter(Boolean);

for (const sentence of sentences) {

  if (sceneBases.length >= 8) {
    break;
  }

  const words=
    normalizeWords(sentence)
      .split(/\s+/)
      .filter(Boolean);

  /*
   * Long narration sentence:
   * create chronological visual concepts
   * instead of one huge search query.
   */
  if (words.length > 12) {

    for (
      let i=0;
      i<words.length && sceneBases.length<8;
      i+=8
    ) {
      addScene(
        words.slice(i,i+8).join(' ')
      );
    }

  } else {

    addScene(sentence);
  }
}

/*
 * Fallback concepts if the script is very short.
 */
if (sceneBases.length < 4) {

  for (
    const part of topic.split(
      /[،,؛;]+|\s+و(?=[\u0600-\u06FF])/u
    )
  ) {

    if (sceneBases.length >= 8) {
      break;
    }

    addScene(
      part.replace(/^و+/u,'').trim()
    );
  }
}

if (sceneBases.length < 2) {
  addScene(title);
  addScene(topic);
}

const videoTerms=[];

for (const scene of sceneBases) {

  const term=
    styledTerm(scene);

  if (
    term &&
    !videoTerms.includes(term)
  ) {
    videoTerms.push(term);
  }

  if (videoTerms.length >= 8) {
    break;
  }
}

return [{
  json:{
    ...$json,

    video_script:script,
    video_terms:videoTerms,

    visual_style:visualStyle,

    script_mode:
      providedScript
        ? 'manual'
        : 'auto'
  }
}];

const store=$getWorkflowStaticData('global');

const jobs=
  Array.isArray(store.jobs)
    ? store.jobs
    : [];

return jobs
  .filter(j => {

    if (!j.task_id) {
      return false;
    }

    if (
      j.status === 'submitted' ||
      j.status === 'processing' ||
      !j.status
    ) {
      return true;
    }

    if (
      j.status === 'completed' &&
      !j.telegram_video_sent
    ) {
      return true;
    }

    return false;
  })
  .slice(0,20)
  .map(j => ({
    json:{
      task_id:j.task_id,
      chat_id:j.chat_id,
      telegram_id:j.telegram_id,
      video_subject:j.topic,
      created_at:j.created_at
    }
  }));

const responses=$input.all();
const contexts=$items('Load Pending Jobs');

const store=$getWorkflowStaticData('global');

if (!Array.isArray(store.jobs)) {
  store.jobs=[];
}

const out=[];

for (let i=0; i<responses.length; i++) {

  const ctx=contexts[i]?.json;
  const payload=responses[i]?.json?.body?.data ?? responses[i]?.json?.data;

  if (!ctx || !payload) {
    continue;
  }

  const progress=Number(payload.progress || 0);

  let status='processing';

  if (
    payload.state === -1 ||
    payload.failed_stage ||
    payload.error
  ) {
    status='failed';
  }

  const hasVideos =
    (
      Array.isArray(payload.videos) &&
      payload.videos.length > 0
    ) ||
    (
      Array.isArray(payload.combined_videos) &&
      payload.combined_videos.length > 0
    );

  if (
    progress >= 100 ||
    hasVideos
  ) {
    status='completed';
  }

  const index=store.jobs.findIndex(
    j => j.task_id === ctx.task_id
  );

  if (index < 0) {
    continue;
  }

  const firstNotice=
    !store.jobs[index].auto_poll_notice_sent;

  store.jobs[index]={
    ...store.jobs[index],
    status,
    progress,
    state:payload.state,
    failed_stage:payload.failed_stage ?? null,
    error:payload.error ?? null,
    videos:payload.videos ?? null,
    combined_videos:payload.combined_videos ?? null,
    auto_poll_notice_sent:true,
    last_polled_at:new Date().toISOString()
  };

  out.push({
    json:{
      ...ctx,
      status,
      progress,
      state:payload.state,
      send_notice:firstNotice,
      poll_notice:
`🔄 المتابعة التلقائية تعمل

🆔 ${ctx.task_id}

📈 الحالة الحقيقية من Editing-Pingoo:
${progress}%`
    }
  });
}

return out;

const store=$getWorkflowStaticData('global');

if (!Array.isArray(store.jobs)) {
  store.jobs=[];
}

const output=[];

for (const item of $input.all()) {

  const data=item.json;

  if (data.status !== 'completed') {
    continue;
  }

  const index=
    store.jobs.findIndex(
      j => j.task_id === data.task_id
    );

  if (index < 0) {
    continue;
  }

  if (
    store.jobs[index].completion_detected_sent
  ) {
    continue;
  }

  store.jobs[index]={
    ...store.jobs[index],
    completion_detected_sent:true,
    completion_detected_at:
      new Date().toISOString()
  };

  output.push({
    json:{
      ...data,

      completion_notice:
`✅ تم اكتشاف اكتمال الفيديو تلقائياً

🎬 الموضوع:
${data.video_subject || ''}

🆔 Task ID:
${data.task_id}

📈 التقدم:
${data.progress}%

⚙️ الحالة:
completed`
    }
  });
}

return output;

const store=$getWorkflowStaticData('global');

if (!Array.isArray(store.jobs)) {
  store.jobs=[];
}

const out=[];

for (const item of $input.all()) {

  if (item.json.status !== 'completed') {
    continue;
  }

  const index=store.jobs.findIndex(
    j => j.task_id === item.json.task_id
  );

  if (index < 0) {
    continue;
  }

  const job=store.jobs[index];

  const videos=Array.isArray(job.videos)
    ? job.videos
    : [];

  const finalPath=videos.find(
    v => String(v).includes('final-1.mp4')
  ) || videos[0];

  if (!finalPath) {
    continue;
  }

  const finalUrl=
    'http://moneyprinterturbo-api:8080' +
    finalPath;

  store.jobs[index]={
    ...job,
    final_video_path:finalPath,
    final_video_url:finalUrl,
    video_captured:true,
    video_captured_at:new Date().toISOString()
  };

  out.push({
    json:{
      ...item.json,
      final_video_path:finalPath,
      final_video_url:finalUrl,
      video_captured:true
    }
  });
}

return out;

const downloaded=$input.all();

const contexts=
  $items('Capture Final Video');

return downloaded.map(
  (item,index) => {

    const ctx=
      contexts[index]?.json;

    if (!ctx) {
      throw new Error(
        'FINAL_VIDEO_CONTEXT_NOT_FOUND'
      );
    }

    if (!item.binary?.video) {
      throw new Error(
        'FINAL_VIDEO_BINARY_NOT_FOUND'
      );
    }

    item.binary.video.fileName =
      `pingoo-${ctx.task_id}.mp4`;

    item.binary.video.mimeType =
      'video/mp4';

    return {
      json:{
        ...ctx
      },
      binary:item.binary
    };
  }
);

const results=$input.all();

const contexts=
  $items('Attach Final Video Context');

const store=
  $getWorkflowStaticData('global');

if (!Array.isArray(store.jobs)) {
  store.jobs=[];
}

const out=[];

for (
  let i=0;
  i<results.length;
  i++
) {

  const ctx=
    contexts[i]?.json;

  if (!ctx) {
    continue;
  }

  const index=
    store.jobs.findIndex(
      j => j.task_id === ctx.task_id
    );

  if (index < 0) {
    continue;
  }

  const messageId=
    results[i]?.json?.message_id ??
    results[i]?.json?.result?.message_id ??
    null;

  store.jobs[index]={
    ...store.jobs[index],

    telegram_video_sent:true,

    telegram_video_sent_at:
      new Date().toISOString(),

    telegram_video_message_id:
      messageId
  };

  out.push({
    json:{
      ...ctx,
      telegram_video_sent:true,
      telegram_video_message_id:
        messageId
    }
  });
}

return out;
